-- =====================================================================
-- Web sitesi: kurumsal sayfalar (Hakkımızda, teknoloji, kalite...)
--
-- Adres: /<dil>/<slug>  (ör. /tr/hakkimizda). Gövde metni ürünlerdeki gibi
-- sade biçimde: paragraflar, "## " ara başlık, "> " alıntı, "- " madde.
-- Başlangıç içeriği eski mbdentaire.com sayfalarından alınmıştır
-- (doğrulanamayan müşteri yorumları alınmadı).
-- =====================================================================

create table cms_pages (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (
    slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) <= 60
    and slug not in ('urunler', 'iletisim', 'vaka-gonder', 'admin', 'giris', 'auth', 'api', 'sayfa')
  ),
  "group" text not null default 'kurumsal' check ("group" in ('kurumsal', 'teknoloji', 'kalite', 'diger')),
  title jsonb not null default '{}'::jsonb check (is_i18n_text(title)),
  summary jsonb not null default '{}'::jsonb check (is_i18n_text(summary)),
  body jsonb not null default '{}'::jsonb check (is_i18n_text(body)),
  seo_title jsonb not null default '{}'::jsonb check (is_i18n_text(seo_title)),
  seo_description jsonb not null default '{}'::jsonb check (is_i18n_text(seo_description)),
  image_path text,
  gallery text[] not null default '{}',
  show_in_footer boolean not null default true,
  sort integer not null default 0,
  is_active boolean not null default true,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid()
);
create index on cms_pages ("group", sort) where deleted_at is null;

create trigger cms_pages_touch before update on cms_pages for each row execute function cms_touch();
create trigger audit_cms_pages after insert or update or delete on cms_pages for each row execute function audit_trigger();

alter table cms_pages enable row level security;
create policy cms_pages_public_read on cms_pages for select to anon, authenticated
  using (deleted_at is null and is_active);
create policy cms_pages_editor_all on cms_pages for all to authenticated
  using (can_manage_site()) with check (can_manage_site());
grant select on cms_pages to anon;
grant select, insert, update, delete on cms_pages to authenticated;

-- Çöp kutusu temizliği sayfaları da kapsasın
create or replace function cms_purge_trash()
returns integer language plpgsql security definer set search_path = public as $$
declare n integer := 0; c integer;
begin
  delete from cms_slides where deleted_at < now() - interval '30 days';
  get diagnostics c = row_count; n := n + c;
  delete from cms_announcements where deleted_at < now() - interval '30 days';
  get diagnostics c = row_count; n := n + c;
  delete from cms_products where deleted_at < now() - interval '30 days';
  get diagnostics c = row_count; n := n + c;
  delete from cms_stories where deleted_at < now() - interval '30 days';
  get diagnostics c = row_count; n := n + c;
  delete from cms_pages where deleted_at < now() - interval '30 days';
  get diagnostics c = row_count; n := n + c;
  return n;
end $$;
revoke execute on function cms_purge_trash() from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- Başlangıç içeriği (TR / EN / FR)
-- ---------------------------------------------------------------------
insert into cms_pages (slug, "group", title, summary, body, sort) values
  ('hakkimizda', 'kurumsal', '{"tr": "Hakkımızda", "en": "About us", "fr": "À propos"}'::jsonb, '{"tr": "İzmir''de, hekimler için dijital diş protez laboratuvarı.", "en": "A digital dental laboratory for dentists, in Izmir.", "fr": "Un laboratoire de prothèse dentaire numérique pour les praticiens, à Izmir."}'::jsonb, '{"tr": "## Sektörde Kalite ve Yenilikçiliğin Adı\n\nMB Dental olarak, dental sektöründe yüksek kaliteli malzemeler ve yenilikçi çözümler sunma misyonuyla hareket ediyoruz. Global olarak kendini kanıtlamış tedarikçilerden temin ettiğimiz CE sertifikalı ürünlerimizle, müşterilerimize en güvenilir ve etkili çözümleri sunmayı hedefliyoruz.\n\nSektördeki bilgi birikimimiz ve tecrübemizle, sürekli gelişim ve mükemmellik prensipleri doğrultusunda çalışıyoruz. Müşteri memnuniyetini en üst düzeyde tutarak, dental sağlık profesyonellerinin ihtiyaçlarına en uygun çözümleri sağlamak için buradayız. MB Dental ailesi olarak, kaliteli malzeme, doğru ekipman ve profesyonel hizmet anlayışımızla dental sağlık sektöründe fark yaratmaya devam ediyoruz.\n\n## Malzeme ve ekipman\n\nMB Dental tüm ürünlerinde dünyaca ünlü dental malzeme tedarikçilerinin CE sertifikalı malzemelerini kullanmaktadır. Bu malzemeler, global olarak kendini kanıtlamış tedarikçiler tarafından sağlanan ekipmanlarda işlenir. MB Dental için kaliteli malzeme ve doğru ekipman, kaliteli ürüne giden yolda ilk adımdır.", "en": "## The Name of Quality and Innovation in the Sector\n\nAt MB Dental, we are driven by our mission to provide high quality materials and innovative solutions in the dental industry. We aim to provide the most reliable and effective solutions to our customers with our CE certified products from globally proven suppliers.\n\nWith our knowledge and experience in the sector, we work in line with the principles of continuous development and excellence. We are here to provide the most suitable solutions to the needs of dental health professionals by keeping customer satisfaction at the highest level. As the MB Dental family, we continue to make a difference in the dental health sector with our understanding of quality materials, the right equipment and professional service.\n\n## Materials and equipment\n\nMB Dental uses CE certified materials from world-renowned dental material suppliers in all its products. These materials are processed on equipment provided by globally proven suppliers. For MB Dental, quality materials and the right equipment are the first step towards quality products.", "fr": "## Nom de la qualité et de l''innovation dans le secteur\n\nEn tant que MB Dental, nous avons pour mission de fournir des matériaux de haute qualité et des solutions innovantes dans le secteur dentaire. Nous visons à fournir les solutions les plus fiables et les plus efficaces à nos clients grâce à nos produits certifiés CE provenant de fournisseurs ayant fait leurs preuves à l''échelle mondiale.\n\nForts de nos connaissances et de notre expérience dans le secteur, nous travaillons selon les principes du développement continu et de l''excellence. Nous sommes là pour fournir les solutions les plus adaptées aux besoins des professionnels de la santé dentaire en maintenant la satisfaction du client au plus haut niveau. En tant que famille MB Dental, nous continuons à faire la différence dans le secteur de la santé dentaire grâce à notre compréhension des matériaux de qualité, de l''équipement adéquat et du service professionnel.\n\n## Matériaux et équipement\n\nMB Dental utilise des matériaux certifiés CE provenant de fournisseurs de matériaux dentaires de renommée mondiale dans tous ses produits. Ces matériaux sont traités sur des équipements fournis par des fournisseurs de renommée mondiale. Pour MB Dental, des matériaux de qualité et le bon équipement sont la première étape vers un produit de qualité."}'::jsonb, 10),
  ('3d-tasarim', 'teknoloji', '{"tr": "3D tasarım", "en": "3D design", "fr": "Conception 3D"}'::jsonb, '{"tr": "Ölçü ya da ağız içi tarama: her vaka iyi bir modelle başlar.", "en": "Impression or intraoral scan: every case starts with a good model.", "fr": "Empreinte ou scan intra-oral : chaque cas commence par un bon modèle."}'::jsonb, '{"tr": "Diş protezinde yüksek uyum ve dengeye giden yol iyi bir model ile başlar.\n\nİster konvansiyonel ölçüler olsun, ister ağız içi tarama dosyaları MB Dental müşterilerinden gelen tüm materyali iyi bir modele dönüştürmek için gereken hassasiyeti gösterir.\n\n## İyi bir model için\n\nAlçı modeller yüksek hız ve hassasiyete sahip 3 Shape tarayıcılar ile taranarak tasarıma hazır hale getirilirken, IOS çıktıları bir yandan altyapı tasarımı için kullanılıp, diğer yandan en hassas 3D printerlar ile hiçbir kayba uğramadan modellere dönüşmektedir. MB Dental tüm indikasyonları dijital ortamda tasarlayabilecek altyapıya ve tecrübeye sahip teknisyenleriyle tüm müşterilerinin son teknolojiye ulaşmasını sağlamaktadır. MB Dental kendi üretim altyapısına sahip olan müşterilerine tarama ve tasarım desteği de vermekte ve yıllar boyunca geliştirdiği tasarım bilgisini müşterileriyle tereddüt etmeden paylaşmaktadır.", "en": "The road to high fit and balance in dentures starts with a good model.\n\nWhether conventional impressions or intraoral scan files, MB Dental takes the necessary care to transform all material from its clients into a good model.\n\n## For a good model\n\nWhile plaster models are scanned with 3 Shape scanners with high speed and precision and made ready for design, IOS outputs are used for infrastructure design on the one hand and on the other hand, they are transformed into models with the most sensitive 3D printers without any loss. MB Dental ensures that all its customers have access to the latest technology with its technicians who have the infrastructure and experience to design all indications in digital environment. MB Dental also provides scanning and design support to its customers who have their own production infrastructure and shares the design knowledge it has developed over the years with its customers without hesitation.", "fr": "Le chemin vers l''harmonie et l''équilibre des prothèses dentaires commence par un bon modèle.\n\nQu''il s''agisse de mesures conventionnelles ou de fichiers de scanners intra-oraux, MB Dental fait preuve de la précision nécessaire pour transformer tout le matériel de ses clients en un bon modèle.\n\n## Pour un bon modèle\n\nAlors que les modèles en plâtre sont scannés avec des scanners 3 Shape à grande vitesse et précision et préparés pour la conception, les sorties IOS sont utilisées pour la conception de l''infrastructure d''une part et d''autre part, elles sont transformées en modèles avec les imprimantes 3D les plus sensibles sans aucune perte. MB Dental veille à ce que tous ses clients aient accès à la technologie la plus récente grâce à ses techniciens qui disposent de l''infrastructure et de l''expérience nécessaires pour concevoir toutes les indications dans un environnement numérique. MB Dental fournit également un soutien en matière de numérisation et de conception à ses clients qui disposent de leur propre infrastructure de production et partage sans hésitation les connaissances en matière de conception développées au fil des ans avec ses clients."}'::jsonb, 20),
  ('cnc-isleme', 'teknoloji', '{"tr": "CNC işleme", "en": "CNC machining", "fr": "Usinage CNC"}'::jsonb, '{"tr": "Zirkondan titanyuma, kendi makine parkurumuzda frezeleme.", "en": "From zirconia to titanium, milled on our own machines.", "fr": "De la zircone au titane, usinage sur notre propre parc machines."}'::jsonb, '{"tr": "Zirkon malzemenin dental sektörde kullanımının yaygınlaşmaya başlamasıyla birlikte MB Dental CNC işleme yöntemini yetenekleri arasına katarak ilk uygulayıcılarından biri olmuştur. Yaptığı yatırımlarla her zaman son teknolojiyi takip eden MB Dental, en iyi malzeme ve ekipmanlarla, en iyi ürüne ulaşma hedefini bugün sahip olduğu makine parkuru ile gerçekleştirmektedir. CNC işleme yöntemi günümüzde birçok malzemenin işlenerek diş protezi olarak kullanılmasına olanak sağlamaktadır.\n\n## Metal işleme\n\nMB Dental makine parkında standart metal blokların yanı sıra premill parçaları işlemek için özelleşmiş tezgahlar bulunmaktadır. Kişiye özel tasarlanan implant abutment parçalar başta olmak üzere premill parçalar bu tezgahlarda işlenmekte ve yüksek hassasiyete sahip ürünler üretime kazandırılmaktadır.\n\n## Malzemeler\n\n- Zirkon Bloklar\n- CoCr Blokları\n- Titanyum Blokları\n- Döküm Blokları\n- PMMA Blokları\n- Titanyum Premill Blokları\n- Seramik Bloklar\n- PEEK Bloklar", "en": "With the widespread use of zirconia material in the dental sector, MB Dental added CNC machining method to its capabilities and became one of the first practitioners. MB Dental, which always follows the latest technology with its investments, realizes its goal of achieving the best product with the best materials and equipment with the machine park it has today. Today, CNC machining method allows many materials to be processed and used as dental prosthesis.\n\n## Metal processing\n\nIn addition to standard metal blocks, the MB Dental machine park includes specialized machines for processing premill parts. Premill parts, especially custom-designed implant abutment parts, are processed on these machines and high-precision products are brought to production.\n\n## Materials\n\n- Zircon Blocks\n- CoCr Blocks\n- Titanium Blocks\n- Casting Blocks\n- PMMA Blocks\n- Titanium Premill Blocks\n- Ceramic Blocks\n- PEEK Blocks", "fr": "Avec l''utilisation généralisée du matériau zircone dans le secteur dentaire, MB Dental est devenu l''un des premiers praticiens de la méthode d''usinage CNC. MB Dental, qui suit toujours les dernières technologies dans ses investissements, réalise son objectif d''obtenir le meilleur produit avec les meilleurs matériaux et équipements grâce au parc de machines dont elle dispose aujourd''hui. La méthode d''usinage CNC permet aujourd''hui de traiter de nombreux matériaux et de les utiliser comme prothèses dentaires.\n\n## Traitement des métaux\n\nOutre les blocs métalliques standard, le parc de machines MB Dental dispose de machines spécialisées pour l''usinage de pièces de pré-fabrication. Ces machines permettent d''usiner des pièces de pré-fabrication, en particulier des piliers d''implants sur mesure, et d''obtenir des produits de haute précision.\n\n## Matériaux\n\n- Blocs de zircone\n- Blocs CoCr\n- Blocs de titane\n- Blocs de coulée\n- Blocs de PMMA\n- Blocs Premill en titane\n- Blocs de céramique\n- Blocs PEEK"}'::jsonb, 30),
  ('3d-baski', 'teknoloji', '{"tr": "3D baskı ve modelleme", "en": "3D printing and modelling", "fr": "Impression et modélisation 3D"}'::jsonb, '{"tr": "Modeller ve döküm altyapıları için hassas 3D baskı.", "en": "Precise 3D printing for models and casting frameworks.", "fr": "Impression 3D précise pour modèles et armatures coulées."}'::jsonb, '{"tr": "## Geleceğin Teknolojisiyle Kişiye Özel Protezler\n\nMB Dental, diş protez üretiminde en son 3D baskı ve modelleme teknolojilerini kullanarak, hastalarınıza en yüksek hassasiyet ve kaliteyi sunar. Bu yenilikçi teknoloji sayesinde, karmaşık protez tasarımlarını kısa sürede ve büyük bir doğrulukla hayata geçiriyoruz. 3D modelleme, her hasta için kişiselleştirilmiş çözümler sunmamızı sağlarken, protezlerin en küçük detaylarına kadar mükemmel bir uyum göstermesini garanti eder. Teknolojik ilerlemelerle diş sağlığında fark yaratmak için buradayız.", "en": "## Personalized Prostheses with Future Technology\n\nMB Dental uses the latest 3D printing and modeling technologies in the production of dental prostheses, offering your patients the highest precision and quality. Thanks to this innovative technology, we bring complex denture designs to life in a short time and with great accuracy. 3D modeling allows us to provide personalized solutions for each patient, guaranteeing a perfect fit of the prosthesis down to the smallest details. We are here to make a difference in dental health with technological advances.", "fr": "## Des prothèses personnalisées grâce à la technologie du futur\n\nMB Dental offre à vos patients la plus haute précision et qualité en utilisant les dernières technologies d''impression 3D et de modélisation dans la production de prothèses dentaires. Grâce à cette technologie innovante, nous réalisons des designs prothétiques complexes en peu de temps et avec une grande précision. La modélisation 3D nous permet de proposer des solutions personnalisées à chaque patient, en garantissant un ajustement parfait de la prothèse dans les moindres détails. Nous sommes là pour faire la différence en matière de santé dentaire grâce aux avancées technologiques."}'::jsonb, 40),
  ('kalite', 'kalite', '{"tr": "Kalite ve son kontrol", "en": "Quality and final control", "fr": "Qualité et contrôle final"}'::jsonb, '{"tr": "ISO 9001 ve ISO 13485; her iş laboratuvardan çıkmadan kontrol edilir.", "en": "ISO 9001 and ISO 13485; every case is checked before it leaves the lab.", "fr": "ISO 9001 et ISO 13485 ; chaque travail est contrôlé avant de quitter le laboratoire."}'::jsonb, '{"tr": "## ISO 9001 ve ISO 13485\n\nMB Dental tüm İş ve üretim süreçlerini ISO 9001:2015 Kalite Yönetim Sistemi ve ISO 13485:2016 Tıbbi Cihazlar İçin Kalite Yönetim Sistemi gerekliliklerine uygun olarak yürütmektedir.\n\n## Son kontrol süreci\n\nMB Dental tarafından üretilen tüm ürünler üretim sırasında sektörde deneyimli Usta Teknisyenler tarafından takip ve kontrol edilir. Bu süreçte teknisyenler müşteriler ile kendi dillerinde iletişim kurar, müşteriden gelen talepleri sahaya en hızlı ve doğru şekilde yansıtırlar.\n\n## Takip ve kontrol\n\nTüm MB Dental ürünler laboratuvardan çıkmadan önce detaylı olarak Usta Teknisyenler tarafından kontrol edilir ve onaylanır.\n\n## Bizimle kendi dilinizde konuşun\n\nMB Dental olarak, müşteri memnuniyetini ön planda tutuyoruz. Ekibimiz, farklı dillerde hizmet sunarak, sizinle anlaşılması kolay ve verimli bir iletişim sağlar.\n\n## Alanında uzman teknisyenlerle çalışın\n\nLaboratuvarımızda, diş protezleri ve implantlar konusunda uzmanlaşmış master teknisyenler görev almaktadır. Yılların deneyimine sahip profesyonellerimiz, her projede en yüksek kalitede işçilik sunar.\n\n## Tüm ürünleriniz %100 kontrol altında\n\nMB Dental''de ürettiğimiz tüm diş protezleri ve ilgili ürünler, titiz bir kalite kontrol sürecinden geçer. Her aşamada yüksek standartlara uygunluk sağlanır ve ürünlerimiz sıkı kalite testlerinden geçirilir.", "en": "## ISO 9001 and ISO 13485\n\nMB Dental conducts all business and production processes in accordance with the requirements of ISO 9001:2015 Quality Management System and ISO 13485:2016 Quality Management System for Medical Devices.\n\n## Final control process\n\nAll products manufactured by MB Dental are monitored and controlled by experienced Master Technicians during production. In this process, technicians communicate with customers in their own language and reflect the demands of the customer to the field in the fastest and most accurate way.\n\n## Monitoring and control\n\nAll MB Dental products are checked and approved in detail by Master Technicians before leaving the laboratory.\n\n## Speak to us in your own language\n\nAt MB Dental, we prioritize customer satisfaction. Our team offers services in different languages, ensuring an easy-to-understand and efficient communication with you.\n\n## Work with expert technicians\n\nOur laboratory is staffed by master technicians specialized in dental prosthetics and implants. With years of experience, our professionals deliver the highest quality workmanship on every project.\n\n## All your products under 100% control\n\nAll the dentures and related products we produce at MB Dental undergo a rigorous quality control process. High standards are met at every stage and our products undergo stringent quality tests.", "fr": "## ISO 9001 et ISO 13485\n\nMB Dental met en œuvre tous les processus commerciaux et de production conformément aux exigences du système de gestion de la qualité ISO 9001:2015 et du système de gestion de la qualité ISO 13485:2016 pour les dispositifs médicaux.\n\n## Processus de contrôle final\n\nTous les produits fabriqués par MB Dental sont suivis et contrôlés par des maîtres techniciens expérimentés dans le secteur pendant la production. Dans ce processus, les techniciens communiquent avec les clients dans leur propre langue et transmettent les demandes du client au terrain de la manière la plus rapide et la plus précise.\n\n## Suivi et contrôle\n\nTous les produits MB Dental sont contrôlés et approuvés en détail par des Maîtres Techniciens avant de quitter le laboratoire.\n\n## Nous parler dans votre langue\n\nChez MB Dental, la satisfaction du client est notre priorité. Notre équipe fournit des services en plusieurs langues, ce qui garantit une communication efficace et facile à comprendre avec vous.\n\n## Travailler avec des techniciens experts\n\nNotre laboratoire est composé de maîtres techniciens spécialisés dans les prothèses dentaires et les implants. Nos professionnels, qui ont des années d''expérience, offrent un travail de la plus haute qualité pour chaque projet.\n\n## Tous vos produits sont contrôlés à 100 %\n\nToutes les prothèses dentaires et les produits connexes que nous fabriquons chez MB Dental sont soumis à un processus rigoureux de contrôle de la qualité. Des normes élevées sont respectées à chaque étape et nos produits sont soumis à des tests de qualité rigoureux."}'::jsonb, 50)
on conflict (slug) do nothing;
